insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('dinde-teriyaki-brocoli-riz', 'Dinde teriyaki, brocoli et riz', 'Des lanières de dinde laquées d''une sauce teriyaki maison au soja, miel et gingembre, avec du brocoli croquant et du riz. Sucré-salé et prêt en 25 minutes.', 'Se garde 3 jours au réfrigérateur. Se réchauffe à la poêle avec un filet d''eau.', 2, 10, 15, array['plat', 'poele', 'monde']::text[]),
  ('saumon-sesame-nouilles-legumes', 'Saumon au sésame, nouilles de riz et légumes sautés', 'Un pavé de saumon enrobé de graines de sésame et poêlé, servi sur des nouilles de riz sautées avec carottes, poivron et chou, relevées de soja et de citron vert.', 'Se garde 2 jours au réfrigérateur. Se mange aussi froid, en salade.', 2, 15, 15, array['plat', 'poele', 'monde']::text[]),
  ('brandade-cabillaud-legere', 'Brandade de cabillaud légère', 'Du cabillaud poché au lait et à l''ail, écrasé avec des pommes de terre et un peu d''huile d''olive, gratiné au four. La brandade en version plus légère, servie avec une salade verte.', 'Se garde 3 jours au réfrigérateur et se congèle 2 mois.', 4, 20, 45, array['plat', 'four', 'batch-cooking']::text[]),
  ('poulet-champignons-fromage-blanc-riz', 'Poulet aux champignons, sauce au fromage blanc et riz', 'Des morceaux de poulet dorés puis mijotés quelques minutes avec des champignons et une échalote, liés au fromage blanc et à la moutarde au lieu de la crème. Servi avec du riz.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement sans faire bouillir la sauce.', 2, 10, 20, array['plat', 'poele']::text[]),
  ('brochettes-porc-paprika-boulgour', 'Brochettes de porc au paprika, poivrons et boulgour', 'Des cubes de filet de porc marinés au paprika fumé, à l''ail et au citron, enfilés avec des poivrons et des oignons rouges, grillés et servis sur un boulgour à la tomate.', 'Se garde 2 jours au réfrigérateur. Le porc se réchauffe 2 minutes à la poêle.', 2, 20, 20, array['plat', 'poele']::text[]),
  ('veau-citron-epinards-pates', 'Escalopes de veau au citron, épinards et pâtes complètes', 'Des fines tranches de veau saisies et déglacées au citron et à l''ail, avec des épinards fondus et des pâtes complètes au parmesan. Un plat italien simple et rapide.', 'Se garde 2 jours au réfrigérateur. Réchauffer doucement pour ne pas durcir le veau.', 2, 10, 15, array['plat', 'poele']::text[]),
  ('crevettes-tomates-feta-boulgour', 'Crevettes à la tomate et à la feta, boulgour', 'Des crevettes mijotées dans une sauce tomate à l''ail et à l''origan, puis gratinées avec un peu de feta, servies avec du boulgour. Inspiré des tavernes grecques.', 'Se garde 2 jours au réfrigérateur.', 2, 10, 25, array['plat', 'four', 'monde']::text[]),
  ('wraps-poulet-crudites-yaourt', 'Wraps de poulet, crudités et sauce au yaourt', 'Des tortillas garnies de poulet grillé aux épices, de carotte râpée, de chou rouge et de salade, avec une sauce au yaourt et à la ciboulette. À emporter facilement.', 'Le poulet se garde 3 jours au réfrigérateur ; garnir les wraps au moment de les manger.', 2, 15, 10, array['plat', 'poele', 'economique']::text[]),
  ('tofu-gingembre-chou-quinoa', 'Tofu sauté au gingembre, chou et quinoa', 'Des cubes de tofu dorés à la poêle, sautés avec du chou, des carottes et beaucoup de gingembre, sur un lit de quinoa, avec des graines de sésame. Croustillant et rassasiant.', 'Se garde 3 jours au réfrigérateur ; le tofu perd un peu de son croustillant.', 2, 15, 20, array['plat', 'poele', 'monde']::text[]),
  ('salade-lentilles-saumon-fume-oeuf', 'Salade de lentilles, saumon fumé et œuf mollet', 'Des lentilles vertes tièdes à la vinaigrette moutardée, avec des lamelles de saumon fumé, un œuf mollet, de l''échalote et de la mâche. Une salade-repas complète.', 'Les lentilles assaisonnées se gardent 3 jours au réfrigérateur ; ajouter le reste au moment de servir.', 2, 15, 25, array['salade', 'plat']::text[]),
  ('smoothie-fraise-fromage-blanc-avoine', 'Smoothie fraise, fromage blanc et avoine', 'Un smoothie épais mixé avec des fraises, du fromage blanc, du lait, des flocons d''avoine et une banane. Un petit-déjeuner à boire, prêt en 5 minutes.', 'Se boit tout de suite ; se garde au plus quelques heures au réfrigérateur.', 2, 5, 0, array['petit-dejeuner', 'sans-cuisson']::text[]),
  ('toasts-oeufs-brouilles-saumon-fume', 'Toasts d''œufs brouillés et saumon fumé', 'Des tranches de pain grillées garnies d''œufs brouillés crémeux à la ciboulette et de saumon fumé, avec quelques feuilles de mâche. Un petit-déjeuner de week-end.', 'À manger tout de suite.', 2, 5, 8, array['petit-dejeuner', 'poele']::text[]),
  ('soupe-poulet-haricots-blancs-chou', 'Soupe de poulet, haricots blancs et chou', 'Une soupe épaisse et réconfortante au poulet effiloché, haricots blancs, chou, carottes et tomates, parfumée au thym et au laurier. Un repas complet dans un bol.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 20, 40, array['soupe', 'plat', 'mijote', 'batch-cooking']::text[]),
  ('gratin-courgettes-poulet-ricotta', 'Gratin de courgettes au poulet et à la ricotta', 'Des rondelles de courgettes, du poulet émincé et une sauce ricotta-œufs aux herbes, gratinés au parmesan. Servi avec un peu de riz pour un repas complet.', 'Se garde 3 jours au réfrigérateur. Se réchauffe au four.', 4, 20, 35, array['plat', 'four', 'batch-cooking']::text[]),
  ('poivrons-farcis-dinde-riz', 'Poivrons farcis à la dinde et au riz', 'Des poivrons garnis d''une farce de dinde hachée, riz, tomates et épices, cuits au four jusqu''à être fondants, et servis avec un yaourt aux herbes.', 'Se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 25, 45, array['plat', 'four', 'batch-cooking']::text[]),
  ('curry-poulet-patate-douce-epinards', 'Curry de poulet, patate douce et épinards', 'Un curry doux de poulet et de patate douce mijotés dans une sauce tomate épicée, avec des épinards et un yaourt ajouté en fin de cuisson. Servi avec du riz basmati.', 'Se garde 3 jours au réfrigérateur et se congèle 3 mois.', 2, 15, 25, array['plat', 'mijote', 'monde']::text[]),
  ('salade-quinoa-crevettes-mangue', 'Salade de quinoa, crevettes et mangue', 'Une salade fraîche de quinoa, crevettes, mangue, concombre, oignon rouge et coriandre, assaisonnée au citron vert. Sucrée, acidulée et pleine de protéines.', 'Se garde 2 jours au réfrigérateur.', 2, 20, 12, array['salade', 'plat', 'monde']::text[]),
  ('bolognaise-dinde-lentilles-pates-completes', 'Bolognaise de dinde aux lentilles et pâtes complètes', 'Une sauce bolognaise mijotée avec de la dinde hachée, des lentilles corail qui fondent dans la sauce, des carottes et du céleri, servie sur des pâtes complètes.', 'La sauce se garde 4 jours au réfrigérateur et se congèle 3 mois.', 4, 20, 40, array['plat', 'mijote', 'batch-cooking']::text[]),
  ('cabillaud-pois-chiches-epices-epinards', 'Cabillaud rôti, pois chiches épicés et épinards', 'Des dos de cabillaud rôtis au four sur des pois chiches croustillants au cumin et au paprika, avec des épinards à l''ail et un yaourt citronné.', 'Se garde 2 jours au réfrigérateur ; les pois chiches perdent leur croustillant.', 2, 10, 25, array['plat', 'four']::text[]),
  ('poulet-pesto-courgettes-quinoa', 'Poulet au pesto, courgettes et quinoa', 'Des lanières de poulet et des courgettes poêlées, enrobées de pesto et de tomates cerises, servies sur du quinoa avec un peu de parmesan. Simple, frais et rapide.', 'Se garde 3 jours au réfrigérateur. Se mange aussi froid, en salade.', 2, 10, 15, array['plat', 'poele']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

