insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('dinde-teriyaki-brocoli-riz', 1, 'Cuire le riz dans une casserole d''eau bouillante salée selon le temps indiqué, puis l''égoutter.'),
  ('dinde-teriyaki-brocoli-riz', 2, 'Éplucher et râper le gingembre et l''ail, puis les mélanger avec la sauce soja, le miel, la fécule et l''eau.'),
  ('dinde-teriyaki-brocoli-riz', 3, 'Couper le brocoli en petits bouquets et les cuire 4 minutes à la vapeur ou dans l''eau bouillante : ils doivent rester croquants.'),
  ('dinde-teriyaki-brocoli-riz', 4, 'Couper la dinde en lanières.'),
  ('dinde-teriyaki-brocoli-riz', 5, 'Faire chauffer l''huile dans une poêle à feu vif et saisir la dinde 5 minutes, jusqu''à ce qu''elle soit dorée et cuite à cœur.'),
  ('dinde-teriyaki-brocoli-riz', 6, 'Verser la sauce et laisser bouillonner 1 minute en remuant, jusqu''à ce qu''elle nappe la viande, puis ajouter le brocoli.'),
  ('dinde-teriyaki-brocoli-riz', 7, 'Servir sur le riz, parsemé de graines de sésame.'),
  ('saumon-sesame-nouilles-legumes', 1, 'Faire tremper ou cuire les nouilles selon les indications du paquet, puis les égoutter.'),
  ('saumon-sesame-nouilles-legumes', 2, 'Couper les carottes en fins bâtonnets, le poivron en lanières et émincer le chou. Râper le gingembre.'),
  ('saumon-sesame-nouilles-legumes', 3, 'Presser la face chair des pavés de saumon dans les graines de sésame.'),
  ('saumon-sesame-nouilles-legumes', 4, 'Faire chauffer la moitié de l''huile dans une poêle à feu moyen et cuire le saumon 4 minutes côté sésame, puis 3 minutes de l''autre côté. Le réserver.'),
  ('saumon-sesame-nouilles-legumes', 5, 'Dans un wok à feu vif, faire sauter les légumes et le gingembre 4 minutes avec le reste de l''huile.'),
  ('saumon-sesame-nouilles-legumes', 6, 'Ajouter les nouilles, la sauce soja et le jus de citron vert et faire sauter 2 minutes.'),
  ('saumon-sesame-nouilles-legumes', 7, 'Servir les nouilles avec le saumon et la coriandre.'),
  ('brandade-cabillaud-legere', 1, 'Éplucher les pommes de terre, les couper en morceaux et les cuire 20 minutes dans une casserole d''eau bouillante salée.'),
  ('brandade-cabillaud-legere', 2, 'Pendant ce temps, faire frémir le lait avec l''ail épluché et le laurier, y plonger le cabillaud et pocher 8 minutes à feu doux.'),
  ('brandade-cabillaud-legere', 3, 'Égoutter le poisson en gardant le lait, retirer le laurier et émietter la chair.'),
  ('brandade-cabillaud-legere', 4, 'Préchauffer le four à 200 °C.'),
  ('brandade-cabillaud-legere', 5, 'Écraser les pommes de terre avec l''ail du pochage, l''huile et assez de lait pour une purée souple.'),
  ('brandade-cabillaud-legere', 6, 'Incorporer le cabillaud et le persil ciselé, saler et poivrer.'),
  ('brandade-cabillaud-legere', 7, 'Étaler dans un plat, parsemer d''emmental et enfourner 20 minutes, jusqu''à ce que le dessus soit doré.'),
  ('brandade-cabillaud-legere', 8, 'Servir avec la salade.'),
  ('poulet-champignons-fromage-blanc-riz', 1, 'Cuire le riz dans une casserole d''eau bouillante salée selon le temps indiqué, puis l''égoutter.'),
  ('poulet-champignons-fromage-blanc-riz', 2, 'Équeuter les haricots verts et les cuire 8 minutes dans l''eau bouillante salée.'),
  ('poulet-champignons-fromage-blanc-riz', 3, 'Couper le poulet en cubes, émincer les champignons et l''échalote.'),
  ('poulet-champignons-fromage-blanc-riz', 4, 'Faire chauffer l''huile dans une sauteuse à feu vif et dorer le poulet 5 minutes. Le réserver.'),
  ('poulet-champignons-fromage-blanc-riz', 5, 'Faire revenir l''échalote et les champignons 6 minutes, jusqu''à ce qu''ils aient rendu leur eau et soient dorés.'),
  ('poulet-champignons-fromage-blanc-riz', 6, 'Remettre le poulet, baisser le feu et, hors du feu, ajouter le fromage blanc et la moutarde. Saler et poivrer.'),
  ('poulet-champignons-fromage-blanc-riz', 7, 'Servir avec le riz et les haricots verts, parsemé de persil.'),
  ('brochettes-porc-paprika-boulgour', 1, 'Couper le porc en cubes et le mélanger avec le paprika, l''ail râpé, le jus de citron, la moitié de l''huile et du sel. Laisser mariner 15 minutes.'),
  ('brochettes-porc-paprika-boulgour', 2, 'Couper les poivrons et l''oignon rouge en gros morceaux.'),
  ('brochettes-porc-paprika-boulgour', 3, 'Enfiler le porc et les légumes en alternance sur des piques.'),
  ('brochettes-porc-paprika-boulgour', 4, 'Verser le boulgour dans un saladier, le couvrir d''eau bouillante salée et laisser gonfler 15 minutes, puis l''égoutter.'),
  ('brochettes-porc-paprika-boulgour', 5, 'Couper les tomates en dés et les mélanger au boulgour avec le persil ciselé et le reste de l''huile.'),
  ('brochettes-porc-paprika-boulgour', 6, 'Cuire les brochettes 10 à 12 minutes dans une poêle-gril chaude en les retournant, jusqu''à ce que le porc soit cuit à cœur.'),
  ('brochettes-porc-paprika-boulgour', 7, 'Servir sur le boulgour avec le yaourt en sauce.'),
  ('veau-citron-epinards-pates', 1, 'Cuire les pâtes dans une grande casserole d''eau bouillante salée selon le temps indiqué, puis les égoutter.'),
  ('veau-citron-epinards-pates', 2, 'Couper le veau en fines escalopes et les saler.'),
  ('veau-citron-epinards-pates', 3, 'Faire chauffer l''huile dans une poêle à feu vif et saisir le veau 1 minute de chaque côté. Le réserver.'),
  ('veau-citron-epinards-pates', 4, 'Baisser le feu, ajouter l''ail émincé, puis le jus de citron et l''eau, et gratter le fond de la poêle 1 minute.'),
  ('veau-citron-epinards-pates', 5, 'Ajouter les épinards et mélanger jusqu''à ce qu''ils tombent, puis remettre le veau 1 minute dans la sauce.'),
  ('veau-citron-epinards-pates', 6, 'Servir avec les pâtes, le parmesan râpé, le persil et du poivre.'),
  ('crevettes-tomates-feta-boulgour', 1, 'Préchauffer le four à 200 °C.'),
  ('crevettes-tomates-feta-boulgour', 2, 'Éplucher et émincer l''oignon et l''ail.'),
  ('crevettes-tomates-feta-boulgour', 3, 'Faire chauffer l''huile dans une sauteuse allant au four et faire revenir l''oignon 5 minutes, puis l''ail, les herbes et le piment 1 minute.'),
  ('crevettes-tomates-feta-boulgour', 4, 'Ajouter les tomates, saler et laisser mijoter 8 minutes.'),
  ('crevettes-tomates-feta-boulgour', 5, 'Ajouter les crevettes, émietter la feta par-dessus et enfourner 10 minutes : les crevettes doivent être roses.'),
  ('crevettes-tomates-feta-boulgour', 6, 'Verser le boulgour dans un saladier, le couvrir d''eau bouillante salée et laisser gonfler 15 minutes, puis l''égoutter.'),
  ('crevettes-tomates-feta-boulgour', 7, 'Servir avec le boulgour, le persil et le concombre en rondelles.'),
  ('wraps-poulet-crudites-yaourt', 1, 'Couper le poulet en lanières et le mélanger avec le paprika, le cumin, l''huile et du sel.'),
  ('wraps-poulet-crudites-yaourt', 2, 'Saisir le poulet 6 minutes dans une poêle chaude, jusqu''à ce qu''il soit doré et cuit à cœur.'),
  ('wraps-poulet-crudites-yaourt', 3, 'Râper la carotte, émincer finement le chou rouge et laver la salade.'),
  ('wraps-poulet-crudites-yaourt', 4, 'Mélanger le yaourt avec le jus de citron, la ciboulette ciselée et du sel.'),
  ('wraps-poulet-crudites-yaourt', 5, 'Réchauffer les tortillas 30 secondes dans une poêle sèche.'),
  ('wraps-poulet-crudites-yaourt', 6, 'Garnir les tortillas de salade, de crudités, de poulet et de sauce, puis les rouler serré.'),
  ('tofu-gingembre-chou-quinoa', 1, 'Rincer le quinoa et le cuire 12 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
  ('tofu-gingembre-chou-quinoa', 2, 'Éponger le tofu, le couper en cubes et l''enrober de fécule.'),
  ('tofu-gingembre-chou-quinoa', 3, 'Faire chauffer l''huile dans une grande poêle à feu vif et dorer le tofu 8 minutes en le retournant : il doit être croustillant. Le réserver.'),
  ('tofu-gingembre-chou-quinoa', 4, 'Émincer le chou, couper les carottes en fins bâtonnets, râper le gingembre et l''ail.'),
  ('tofu-gingembre-chou-quinoa', 5, 'Faire sauter les légumes 5 minutes dans la poêle, puis ajouter le gingembre et l''ail 1 minute.'),
  ('tofu-gingembre-chou-quinoa', 6, 'Remettre le tofu avec la sauce soja et le jus de citron vert, et mélanger 1 minute.'),
  ('tofu-gingembre-chou-quinoa', 7, 'Servir sur le quinoa, parsemé de sésame.'),
  ('salade-lentilles-saumon-fume-oeuf', 1, 'Cuire les lentilles 25 minutes dans une casserole d''eau non salée, puis les égoutter.'),
  ('salade-lentilles-saumon-fume-oeuf', 2, 'Cuire les œufs 6 minutes dans l''eau bouillante, les refroidir dans l''eau froide et les écaler.'),
  ('salade-lentilles-saumon-fume-oeuf', 3, 'Éplucher et ciseler l''échalote.'),
  ('salade-lentilles-saumon-fume-oeuf', 4, 'Fouetter la moutarde, le vinaigre, l''huile et du poivre, puis ajouter l''échalote.'),
  ('salade-lentilles-saumon-fume-oeuf', 5, 'Mélanger les lentilles tièdes avec la vinaigrette.'),
  ('salade-lentilles-saumon-fume-oeuf', 6, 'Servir sur la mâche avec le saumon fumé en lamelles, l''œuf coupé en deux et la ciboulette.'),
  ('smoothie-fraise-fromage-blanc-avoine', 1, 'Laver et équeuter les fraises.'),
  ('smoothie-fraise-fromage-blanc-avoine', 2, 'Mettre les fraises, la banane en morceaux, le fromage blanc, le lait et les flocons d''avoine dans un blender.'),
  ('smoothie-fraise-fromage-blanc-avoine', 3, 'Mixer 1 minute, jusqu''à ce que le mélange soit lisse et épais.'),
  ('smoothie-fraise-fromage-blanc-avoine', 4, 'Goûter, ajouter le miel si besoin et servir aussitôt.'),
  ('toasts-oeufs-brouilles-saumon-fume', 1, 'Battre les œufs avec du poivre.'),
  ('toasts-oeufs-brouilles-saumon-fume', 2, 'Faire fondre le beurre dans une poêle à feu doux, verser les œufs et remuer sans cesse 3 à 4 minutes, jusqu''à ce qu''ils soient pris mais crémeux.'),
  ('toasts-oeufs-brouilles-saumon-fume', 3, 'Hors du feu, incorporer le fromage frais et la ciboulette ciselée.'),
  ('toasts-oeufs-brouilles-saumon-fume', 4, 'Faire griller le pain.'),
  ('toasts-oeufs-brouilles-saumon-fume', 5, 'Garnir les tranches d''œufs brouillés, de saumon fumé et de mâche.'),
  ('soupe-poulet-haricots-blancs-chou', 1, 'Éplucher et émincer l''oignon et l''ail. Éplucher les carottes et les couper en dés. Émincer le chou.'),
  ('soupe-poulet-haricots-blancs-chou', 2, 'Faire chauffer l''huile dans une grande cocotte à feu moyen et faire revenir l''oignon et les carottes 5 minutes, puis l''ail 1 minute.'),
  ('soupe-poulet-haricots-blancs-chou', 3, 'Ajouter l''eau, le bouillon, les tomates, le thym et le laurier, et porter à ébullition.'),
  ('soupe-poulet-haricots-blancs-chou', 4, 'Plonger les filets de poulet entiers et laisser frémir 15 minutes.'),
  ('soupe-poulet-haricots-blancs-chou', 5, 'Sortir le poulet et l''effilocher avec deux fourchettes.'),
  ('soupe-poulet-haricots-blancs-chou', 6, 'Ajouter le chou et les haricots blancs égouttés et cuire 15 minutes.'),
  ('soupe-poulet-haricots-blancs-chou', 7, 'Remettre le poulet, poivrer et servir avec le parmesan râpé.'),
  ('gratin-courgettes-poulet-ricotta', 1, 'Préchauffer le four à 200 °C.'),
  ('gratin-courgettes-poulet-ricotta', 2, 'Couper les courgettes en rondelles et les faire revenir 6 minutes à la poêle avec la moitié de l''huile, à feu vif.'),
  ('gratin-courgettes-poulet-ricotta', 3, 'Couper le poulet en fines lanières et le saisir 4 minutes dans la poêle avec le reste de l''huile et l''ail émincé.'),
  ('gratin-courgettes-poulet-ricotta', 4, 'Battre la ricotta avec les œufs, les herbes, la moitié du parmesan, du sel et du poivre.'),
  ('gratin-courgettes-poulet-ricotta', 5, 'Disposer les courgettes et le poulet dans un plat, napper de sauce et parsemer du reste de parmesan.'),
  ('gratin-courgettes-poulet-ricotta', 6, 'Enfourner 25 minutes, jusqu''à ce que le dessus soit doré et pris.'),
  ('gratin-courgettes-poulet-ricotta', 7, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante salée, puis l''égoutter, et servir avec le gratin.'),
  ('poivrons-farcis-dinde-riz', 1, 'Cuire le riz 10 minutes dans une casserole d''eau bouillante salée, puis l''égoutter.'),
