join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('dinde-teriyaki-brocoli-riz', 'saumon-sesame-nouilles-legumes', 'brandade-cabillaud-legere', 'poulet-champignons-fromage-blanc-riz', 'brochettes-porc-paprika-boulgour', 'veau-citron-epinards-pates', 'crevettes-tomates-feta-boulgour', 'wraps-poulet-crudites-yaourt', 'tofu-gingembre-chou-quinoa', 'salade-lentilles-saumon-fume-oeuf', 'smoothie-fraise-fromage-blanc-avoine', 'toasts-oeufs-brouilles-saumon-fume', 'soupe-poulet-haricots-blancs-chou', 'gratin-courgettes-poulet-ricotta', 'poivrons-farcis-dinde-riz', 'curry-poulet-patate-douce-epinards', 'salade-quinoa-crevettes-mangue', 'bolognaise-dinde-lentilles-pates-completes', 'cabillaud-pois-chiches-epices-epinards', 'poulet-pesto-courgettes-quinoa')) <> 223 then
    raise exception 'Lignes d''ingrédients manquantes dans le neuvième lot de recettes.';
  end if;
end;
$$;
